content.text:
{
  "name": "ADN4604/ADN4605 高速数字交叉点开关",
  "name_en": "ADN4604/ADN4605 High-Speed Digital Crosspoint Switch",
  "manufacturer": "Analog Devices",
  "description": "ADN4604/ADN4605 是一类高速数字交叉点交换芯片，用于将多个输入通道灵活映射到多个输出通道，并可配置收发通道相关参数，如均衡、驱动、信号选项和端接。实验室中常用于高速数字链路的路由、切换、通道分配与链路调试。",
  "description_en": "The ADN4604/ADN4605 is a family of high-speed digital crosspoint switch ICs used to flexibly route multiple input channels to multiple output channels. It supports configuration of transmitter and receiver related settings such as equalization, drive, signal options, and termination. In laboratories, it is commonly used for high-speed digital link routing, switching, channel assignment, and link debugging.",
  "actions": [
    {
      "action_name": "auto-init",
      "description": "初始化器件寄存器映射并设置输出表相关配置。",
      "description_en": "Initialize the device register map and output-table related configuration."
    },
    {
      "action_name": "auto-write_register",
      "description": "向指定寄存器字段写入配置值。",
      "description_en": "Write a configuration value to a specified register field."
    },
    {
      "action_name": "auto-read_register",
      "description": "读取指定寄存器字段的当前值。",
      "description_en": "Read the current value of a specified register field."
    },
    {
      "action_name": "auto-reset",
      "description": "将交叉点开关复位为默认状态。",
      "description_en": "Reset the crosspoint switch to its default state."
    },
    {
      "action_name": "auto-xpt_update",
      "description": "更新交叉点核心，使通道分配修改生效。",
      "description_en": "Update the crosspoint core so channel assignment changes take effect."
    },
    {
      "action_name": "auto-output_table",
      "description": "设置或查询当前使用的输出表。",
      "description_en": "Set or query the currently active output table."
    },
    {
      "action_name": "auto-assign_output",
      "description": "将指定输入通道分配到某个输出通道。",
      "description_en": "Assign a specified input channel to an output channel."
    },
    {
      "action_name": "auto-tx_config",
      "description": "配置发送端通道参数，如驱动、信号或通道路由设置。",
      "description_en": "Configure transmitter channel settings such as drive, signal, or lane-routing options."
    },
    {
      "action_name": "auto-rx_config",
      "description": "配置接收端通道参数，如均衡或信号设置。",
      "description_en": "Configure receiver channel settings such as equalization or signal options."
    },
    {
      "action_name": "auto-set_termination",
      "description": "设置器件收发通道的端接配置。",
      "description_en": "Configure termination settings for the device transmitter and receiver channels."
    },
    {
      "action_name": "auto-tx_termination",
      "description": "设置或读取发送端端接状态。",
      "description_en": "Set or read the transmitter termination state."
    },
    {
      "action_name": "auto-rx_termination",
      "description": "设置或读取接收端端接状态。",
      "description_en": "Set or read the receiver termination state."
    },
    {
      "action_name": "auto-io_config",
      "description": "按照给定配置执行输入到输出的映射，并配置输出相关参数。",
      "description_en": "Apply input-to-output mapping according to a given configuration and set related output parameters."
    },
    {
      "action_name": "auto-input_config",
      "description": "配置输入通道的均衡和信号相关参数。",
      "description_en": "Configure input-channel equalization and signal-related settings."
    }
  ],
  "tag_hints": [
    "digital crosspoint switch",
    "high-speed signal routing",
    "input-to-output mapping",
    "multichannel digital switching",
    "TX/RX termination control",
    "receiver equalization",
    "signal path configuration"
  ]
}

